import './globals.css';
import type { ReactNode } from 'react';
import type { Metadata, Viewport } from 'next';
import Nav from '@/components/Nav';
import Footer from '@/components/Footer';
import ClientBootstrap from '@/components/ClientBootstrap';
import AudioTour from '@/components/AudioTour';
import VoiceAssistant from '@/components/VoiceAssistant';
import AnalyticsTracker from '@/components/AnalyticsTracker';
import BugReportWidget from '@/components/BugReportWidget';
import JsonLd from '@/components/JsonLd';
import { SITE, pageMetadata, organizationJsonLd } from '@/lib/seo';
import { ThemeProvider } from '@/lib/context/theme-context';
import { NavProvider } from '@/lib/context/nav-context';

// Root metadata — every route inherits these and overrides via
// its own generateMetadata() / pageMetadata() calls.
export const metadata: Metadata = {
  ...pageMetadata({
    title: SITE.defaultTitle,
    description: SITE.description,
    path: '/',
  }),
  title: {
    default: SITE.defaultTitle,
    template: SITE.titleTemplate,
  },
  applicationName: SITE.name,
  authors: [{ name: SITE.orgLegalName }],
  creator: SITE.orgLegalName,
  publisher: SITE.orgLegalName,
  keywords: [
    'accessibility', 'assistive technology', 'screen reader',
    'visual impairment', 'blind', 'low vision', 'NGO', 'open source',
  ],
  formatDetection: { email: false, address: false, telephone: false },
};

export const viewport: Viewport = {
  width: 'device-width',
  initialScale: 1,
  themeColor: [
    { media: '(prefers-color-scheme: light)', color: '#f7f3ed' },
    { media: '(prefers-color-scheme: dark)',  color: '#121212' },
  ],
};

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en" data-theme="light" data-text-size="a" suppressHydrationWarning>
      <head>
        {/*
          Tiny blocking inline script — restores the user's saved
          theme + text-size BEFORE the first paint, so dark / high-
          contrast users don't see a white flash while ClientBootstrap
          hydrates. The keys match lib/client/theme.ts exactly.
          Static export: no per-request nonce; CSP for inline scripts
          is enforced via nginx (script-src 'self' 'sha256-...').
        */}
        <script
          dangerouslySetInnerHTML={{
            __html:
              "(function(){try{var T=['light','dark','high-contrast'];var S=['a','a-plus','a-plus-plus'];var t=localStorage.getItem('teww-theme');var s=localStorage.getItem('teww-size');if(!T.indexOf||T.indexOf(t)<0)t='light';if(S.indexOf(s)<0)s='a';var r=document.documentElement;r.setAttribute('data-theme',t);r.setAttribute('data-text-size',s);}catch(_){}})();",
          }}
        />
        <JsonLd data={organizationJsonLd()} />
      </head>
      <body>
        <a href="#main" className="skip-link">Skip to main content</a>
        <ThemeProvider>
          <NavProvider>
            <Nav />
            <main id="main">{children}</main>
            <Footer />
            <ClientBootstrap />
            <AudioTour />
            <VoiceAssistant />
            <AnalyticsTracker />
            <BugReportWidget />
          </NavProvider>
        </ThemeProvider>
      </body>
    </html>
  );
}

@font-face { font-family: 'Space Grotesk'; src: url('/fonts/SpaceGrotesk-VariableFont_wght.ttf') format('truetype-variations'); font-weight: 300 700; font-display: swap; }
@font-face { font-family: 'DM Sans'; src: url('/fonts/DMSans-VariableFont_opsz_wght.ttf') format('truetype-variations'); font-weight: 100 1000; font-display: swap; }
@font-face { font-family: 'DM Sans'; src: url('/fonts/DMSans-Italic-VariableFont_opsz_wght.ttf') format('truetype-variations'); font-weight: 100 1000; font-style: italic; font-display: swap; }

/*
 * Fallback @font-face declarations with size-adjust + ascent/descent
 * overrides. The browser uses these while the real font files are
 * downloading, so the layout doesn't shift when the swap happens
 * (eliminates ~0.05–0.1 of CLS per page on slow networks).
 */
@font-face {
  font-family: 'Space Grotesk Fallback';
  src: local('Arial');
  size-adjust: 105%;
  ascent-override: 95%;
  descent-override: 25%;
  line-gap-override: 0%;
}
@font-face {
  font-family: 'DM Sans Fallback';
  src: local('Arial');
  size-adjust: 100%;
  ascent-override: 96%;
  descent-override: 24%;
  line-gap-override: 0%;
}

/* Tailwind utilities (shadcn/ui). Preflight is disabled in tailwind.config.js
   so the existing reset below remains the source of truth. */
@tailwind base;
@tailwind components;
@tailwind utilities;

/* ── RESET & TOKENS ─────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
:root {
  --font-display: 'Space Grotesk', 'Space Grotesk Fallback', sans-serif;
  --font-body: 'DM Sans', 'DM Sans Fallback', sans-serif;
  --font-mono: 'DM Mono', 'Courier New', monospace;
  --radius-sm: 4px; --radius-md: 8px; --radius-lg: 12px; --radius-xl: 16px; --radius-full: 9999px;
  --space-1:.25rem;--space-2:.5rem;--space-3:.75rem;--space-4:1rem;--space-6:1.5rem;--space-8:2rem;--space-10:2.5rem;--space-12:3rem;--space-16:4rem;--space-20:5rem;--space-24:6rem;
  --maxw: 1280px;

  /* Header height — used by the topnav and every sticky element that
     sits below it (subnav on /media /about /documents, the story-detail
     reading-progress bar, etc). Keeping it as a variable means future
     nav height changes don't need to hunt down hard-coded 68 px values
     across the stylesheet. */
  --header-height: 68px;

  /*
   * CMS UI redesign — density + sidebar width vars (cms-redesign-plan.md §1).
   * Defaults match comfortable density. Overridden inside the CMS shell via
   * the `[data-density]` attribute on .adm-shell.
   */
  --row-y:    10px;
  --pad-card: 22px;
  --gap:      20px;
  --rail-w:   248px;

  /* Foreground color used on top of --brand / --accent tinted backgrounds. */
  --brand-fg:  #ffffff;
  --accent-fg: #ffffff;
}

/* CMS shell density toggle — overrides --row-y / --pad-card / --gap. */
[data-density="compact"]     { --row-y: 6px;  --pad-card: 16px; --gap: 14px; }
[data-density="comfortable"] { --row-y: 10px; --pad-card: 22px; --gap: 20px; }
[data-theme="light"] {
  --bg:#f6f6fe;--bg-elevated:#fff;--bg-subtle:#eaeaf5;--bg-inverse:#0d0407;
  --fg:#0d0407;--fg-muted:#4a4a6a;--fg-subtle:#8888aa;--fg-inverse:#f6f6fe;
  --border:#d4d4e8;--border-strong:#8888aa;
  --brand:#1f61ff;--brand-hover:#1349d4;--brand-subtle:#eef3ff;
  --accent:#e76021;--accent-hover:#c04c18;--accent-subtle:#fff4ee;
  --focus-ring:#1f61ff;
  --shadow-sm:0 1px 3px rgba(13,4,7,.08),0 1px 2px rgba(13,4,7,.04);
  --shadow-md:0 4px 12px rgba(13,4,7,.10),0 2px 4px rgba(13,4,7,.06);
  --shadow-lg:0 10px 30px rgba(13,4,7,.12),0 4px 8px rgba(13,4,7,.06);
}
[data-theme="dark"] {
  --bg:#0d0410;--bg-elevated:#181326;--bg-subtle:#1e1a2e;--bg-inverse:#f6f6fe;
  --fg:#f6f6fe;--fg-muted:#b0b0cc;--fg-subtle:#666688;--fg-inverse:#0d0407;
  --border:rgba(246,246,254,.10);--border-strong:rgba(246,246,254,.25);
  --brand:#4d7eff;--brand-hover:#7a9fff;--brand-subtle:rgba(31,97,255,.15);
  --accent:#f07a3d;--accent-hover:#ff9f61;--accent-subtle:rgba(231,96,33,.15);
  --focus-ring:#4d7eff;
  --shadow-sm:0 1px 3px rgba(0,0,0,.4);--shadow-md:0 4px 12px rgba(0,0,0,.5);--shadow-lg:0 10px 30px rgba(0,0,0,.6);
}
[data-theme="high-contrast"] {
  --bg:#000;--bg-elevated:#0a0a0a;--bg-subtle:#111;--bg-inverse:#fff;
  --fg:#fff;--fg-muted:#ddd;--fg-subtle:#aaa;--fg-inverse:#000;
  --border:#fff;--border-strong:#fff;
  --brand:#5c8fff;--brand-hover:#89adff;--brand-subtle:#001a66;
  --accent:#ffaa5c;--accent-hover:#ffcc99;--accent-subtle:#4d2000;
  --focus-ring:#ffff00;
  --shadow-sm:0 0 0 2px #fff;--shadow-md:0 0 0 2px #fff;--shadow-lg:0 0 0 3px #fff;
}

[data-text-size="a"]{ font-size:16px; }
[data-text-size="a-plus"]{ font-size:18px; }
[data-text-size="a-plus-plus"]{ font-size:20px; }

html {
  scroll-behavior: smooth;
  /* Anchor jumps (e.g. /about#team) land below the topnav AND the
     subnav, not behind them. Approximate the combined height: topnav
     (--header-height) + subnav (~48 px). */
  scroll-padding-top: calc(var(--header-height) + 56px);
}
body { font-family: var(--font-body); background: var(--bg); color: var(--fg); line-height: 1.6; -webkit-font-smoothing: antialiased; transition: background .25s ease, color .25s ease; min-height: 100vh; }
a { color: var(--brand); text-decoration: none; }
a:hover { color: var(--brand-hover); }
button { font: inherit; }
:focus-visible { outline: 3px solid var(--focus-ring); outline-offset: 2px; border-radius: 4px; }

img { max-width: 100%; display: block; }

/* ── NAV ───────────────────────────────── */
nav.topnav { position: sticky; top: 0; z-index: 100; background: var(--bg-elevated); border-bottom: 1px solid var(--border); box-shadow: var(--shadow-sm); transition: background .25s, border-color .25s; }
.nav-inner { max-width: var(--maxw); margin: 0 auto; padding: 0 var(--space-8); height: var(--header-height); display: flex; align-items: center; justify-content: space-between; gap: var(--space-6); }
.nav-logo { display: flex; align-items: center; cursor: pointer; flex-shrink: 0; background: none; border: none; padding: 0; color: inherit; }
.nav-logo img,
.nav-logo .brand-logo-svg { height: 28px; width: auto; display: block; }
.nav-links { display: flex; align-items: center; gap: var(--space-6); list-style: none; }
.nav-links > li { position: relative; }
.nav-links a, .nav-links button.nav-link-btn { font-family: var(--font-display); font-size: .9rem; font-weight: 500; color: var(--fg-muted); padding: 6px 0; border-bottom: 2px solid transparent; transition: color .15s, border-color .15s; background: none; border-left: none; border-right: none; border-top: none; cursor: pointer; display: inline-flex; align-items: center; gap: 4px; }
.nav-links a:hover, .nav-links a.active, .nav-links button.nav-link-btn:hover, .nav-links button.nav-link-btn.active { color: var(--fg); border-bottom-color: var(--brand); }
.nav-dropdown { position: absolute; top: calc(100% + 6px); left: -16px; min-width: 220px; background: var(--bg-elevated); border: 1px solid var(--border); border-radius: var(--radius-lg); box-shadow: var(--shadow-lg); padding: 8px; opacity: 0; visibility: hidden; transform: translateY(-4px); transition: opacity .15s, transform .15s, visibility .15s; z-index: 110; }
.nav-links > li:hover .nav-dropdown, .nav-links > li:focus-within .nav-dropdown, .nav-dropdown.open { opacity: 1; visibility: visible; transform: translateY(0); }
.nav-dropdown a { display: block; padding: 10px 12px; border-radius: var(--radius-md); border-bottom: none; color: var(--fg); font-weight: 500; font-size: .88rem; }
.nav-dropdown a:hover { background: var(--bg-subtle); color: var(--fg); }

.nav-controls { display: flex; align-items: center; gap: var(--space-3); flex-shrink: 0; }
.icon-btn { width: 38px; height: 38px; border-radius: var(--radius-md); border: 1.5px solid var(--border); background: var(--bg); display: flex; align-items: center; justify-content: center; cursor: pointer; color: var(--fg-muted); font-size: 17px; transition: background .15s, border-color .15s, color .15s; }
.icon-btn:hover { background: var(--bg-subtle); color: var(--fg); border-color: var(--border-strong); }
.text-size-btns { display: flex; border: 1.5px solid var(--border); border-radius: var(--radius-md); overflow: hidden; }
.ts-btn { padding: 5px 10px; background: var(--bg); border: none; cursor: pointer; font-family: var(--font-display); font-size: 11px; font-weight: 700; color: var(--fg-muted); border-right: 1px solid var(--border); transition: background .15s, color .15s; min-width: 30px; }
.ts-btn:last-child { border-right: none; }
.ts-btn.active { background: var(--brand); color: #fff; }
.nav-cta { background: var(--accent); color: #fff; font-family: var(--font-display); font-size: .9rem; font-weight: 600; padding: 9px 20px; border-radius: var(--radius-full); border: none; cursor: pointer; transition: background .15s, transform .1s; white-space: nowrap; display: inline-flex; align-items: center; gap: 6px; }
.nav-cta:hover { background: var(--accent-hover); }
.nav-cta:active { transform: scale(.97); }

/* Skip link */
.skip-link { position: absolute; left: 8px; width: 1px; height: 1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap; background: var(--brand); color: #fff; border-radius: var(--radius-md); z-index: 9999; font-family: var(--font-display); font-weight: 600; }
.skip-link:focus-visible { top: 8px; width: auto; height: auto; padding: 8px 16px; overflow: visible; clip: auto; clip-path: none; color: #fff; }

/* ── PAGE SHELL ──────────────────────────────── */
.page { display: none; }
.page.active { display: block; animation: pageIn .3s ease-out; }
@keyframes pageIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }

/* ── SUBNAV (tabs) ──────────────────────────────
 * Secondary in-page tab bar used by /media, /documents, /about, and
 * anywhere else <Subnav> is mounted. Stays pinned to the top of the
 * viewport (under the global topnav) while the user scrolls through
 * the active tab's content.
 *
 * Sticky positioning relies on:
 *   - top: var(--header-height) so it tucks exactly below the topnav
 *     even if the topnav height changes
 *   - z-index: 90 (one below the topnav's 100) so it slides under the
 *     topnav on scroll, never over it
 *   - No `overflow: hidden` on any ancestor in the page tree (verified
 *     in layout.tsx — main has no overflow set; only html/body have
 *     overflow-x: hidden which doesn't kill sticky on Chromium)
 *
 * Visual treatment: backdrop-blur + slightly translucent background +
 * a subtle box-shadow give the bar a "floating" feel that distinguishes
 * it from the topnav when both are pinned together at the top.
 */
.subnav {
  position: sticky;
  top: var(--header-height);
  z-index: 90;
  background: color-mix(in oklab, var(--bg-elevated) 88%, transparent);
  backdrop-filter: saturate(140%) blur(10px);
  -webkit-backdrop-filter: saturate(140%) blur(10px);
  border-bottom: 1px solid var(--border);
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.04);
}
.subnav-inner { max-width: var(--maxw); margin: 0 auto; padding: 0 var(--space-8); display: flex; gap: var(--space-6); overflow-x: auto; }
.subnav button { font-family: var(--font-display); font-size: .85rem; font-weight: 600; color: var(--fg-muted); padding: 14px 2px; background: none; border: none; border-bottom: 2px solid transparent; cursor: pointer; white-space: nowrap; transition: color .15s, border-color .15s; letter-spacing: .01em; }
.subnav button:hover { color: var(--fg); }
.subnav button.active { color: var(--fg); border-bottom-color: var(--accent); }

.subpage { display: none; }
.subpage.active { display: block; }

/* ── SECTION ────────────────────────────── */
.section { padding: var(--space-20) var(--space-8); }
.section-inner { max-width: var(--maxw); margin: 0 auto; }
.section-alt { background: var(--bg-subtle); }
.section-dark { background: var(--bg-inverse); color: var(--fg-inverse); }
.section-dark .section-title, .section-dark h2, .section-dark h3 { color: var(--fg-inverse); }
.section-dark .section-subtitle, .section-dark p { color: rgba(246,246,254,.75); }
[data-theme="dark"] .section-dark, [data-theme="high-contrast"] .section-dark { background: var(--bg-elevated); color: var(--fg); }
[data-theme="dark"] .section-dark .section-subtitle, [data-theme="dark"] .section-dark p { color: var(--fg-muted); }

/* ── HERO (photo-led) ─────────────────────────── */
.hero {
  position: relative; overflow: hidden;
  min-height: 720px; height: calc(100vh - 68px); max-height: 860px;
  display: flex; align-items: flex-end;
  border-bottom: 1px solid var(--border);
  background: #0d0407;
}
/*
 * `--hero-image` is the URL the home page hero photo uses. Set it
 * via the inline style on `.hero-photo` (driven by CMS data).
 * Fallback below keeps the page intact if no CMS value is configured.
 */
.hero-photo {
  position: absolute; inset: 0; z-index: 0;
  --hero-image: url('https://images.unsplash.com/photo-1509062522246-3755977927d7?auto=format&fit=crop&w=2400&q=80');
  background-image:
    linear-gradient(180deg, rgba(13,4,7,.18) 0%, rgba(13,4,7,.35) 40%, rgba(13,4,7,.88) 100%),
    linear-gradient(90deg, rgba(13,4,7,.6) 0%, rgba(13,4,7,0) 55%),
    var(--hero-image);
  background-size: cover; background-position: center 35%;
  filter: saturate(.95) contrast(1.05);
}
.hero-photo::after {
  /* warm tone wash to blend with brand orange */
  content:''; position:absolute; inset:0;
  background: linear-gradient(115deg, rgba(19,73,212,.28) 0%, rgba(0,0,0,0) 45%, rgba(231,96,33,.22) 100%);
  mix-blend-mode: screen;
}
/* Decorative low-opacity graphics layer */
.hero-graphics { position:absolute; inset:0; z-index:1; pointer-events:none; overflow:hidden; }
.hero-graphics svg.hg-eye {
  position:absolute; right:-80px; top:8%;
  width: 560px; height:auto; opacity:.10;
  color:#fff;
  animation: hgFloat 14s ease-in-out infinite;
  will-change: transform;
}
.hero-graphics svg.hg-rings {
  position:absolute; left: 6%; top: 18%;
  width: 380px; opacity:.14; color:#fff;
  animation: hgSpin 60s linear infinite;
  will-change: transform;
}
@media (prefers-reduced-motion: reduce) {
  .hero-graphics svg.hg-eye,
  .hero-graphics svg.hg-rings,
  .hero-graphics .hg-live .dot { animation: none; }
}
.hero-graphics .hg-dots {
  position:absolute; right: 8%; bottom: 26%;
  width: 220px; height: 220px; opacity:.35;
  background-image: radial-gradient(circle, rgba(255,255,255,.45) 1.4px, transparent 1.6px);
  background-size: 18px 18px;
  -webkit-mask-image: radial-gradient(circle at center, #000 40%, transparent 72%);
          mask-image: radial-gradient(circle at center, #000 40%, transparent 72%);
}
.hero-graphics .hg-line {
  position:absolute; left:0; right:0;
  height:1px; background: rgba(255,255,255,.08);
}
.hero-graphics .hg-line.l1 { top: 32%; }
.hero-graphics .hg-line.l2 { top: 62%; background: rgba(231,96,33,.20); }
.hero-graphics .hg-live {
  position:absolute; top: 28px; right: 32px;
  display:inline-flex; align-items:center; gap:8px;
  padding: 7px 12px 7px 10px; border-radius: 999px;
  background: rgba(255,255,255,.08); backdrop-filter: blur(10px);
  border: 1px solid rgba(255,255,255,.15);
  font-family: var(--font-display); font-size:.7rem; font-weight:600;
  letter-spacing:.12em; text-transform:uppercase; color:#fff;
}
.hero-graphics .hg-live .dot { width:6px; height:6px; border-radius:50%; background: var(--accent); box-shadow: 0 0 0 4px rgba(231,96,33,.25); animation: pulse 2s ease-in-out infinite; }
@keyframes hgFloat { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-18px); } }
@keyframes hgSpin { to { transform: rotate(360deg); } }

.hero-inner {
  position: relative; z-index: 2;
  width: 100%; max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 var(--space-8) 72px;
  color: #fff;
}
.hero-eyebrow {
  font-family: var(--font-display); font-size: .72rem; font-weight: 600;
  letter-spacing: .16em; text-transform: uppercase;
  color: #fff; opacity: .85;
  margin-bottom: 22px;
  display: inline-flex; align-items: center; gap: 10px;
}
.hero-eyebrow::before { content: ''; width: 28px; height: 2px; background: var(--accent); }
.hero-title {
  font-family: var(--font-display);
  font-size: clamp(2.4rem, 5vw, 4.4rem);
  font-weight: 700; line-height: .98;
  letter-spacing: -.04em;
  color: #fff; margin-bottom: 22px;
  text-wrap: balance; max-width: 820px;
  text-shadow: 0 2px 40px rgba(0,0,0,.4);
}
.hero-title em {
  color: #fff; font-style: normal; position: relative; display: inline-block;
}
.hero-title em::after {
  content: ''; position: absolute; left: 0; right: 0; bottom: 6px;
  height: 14px; background: var(--accent);
  opacity: .9; z-index: -1; border-radius: 2px;
}
.hero-body { display:none; }
.hero-sub {
  font-size: clamp(1rem, 1.4vw, 1.2rem);
  line-height: 1.55;
  color: rgba(255,255,255,.86);
  max-width: 640px;
  margin: 0 0 28px;
  text-shadow: 0 1px 20px rgba(0,0,0,.4);
}

/* Impact strip */
.hero-impact {
  display: grid; grid-template-columns: repeat(4, auto);
  gap: 0;
  margin: 0 0 28px;
  max-width: 720px;
  border-top: 1px solid rgba(255,255,255,.18);
  border-bottom: 1px solid rgba(255,255,255,.18);
}
.hero-impact .hi-cell {
  padding: 18px 28px 18px 0;
  border-right: 1px solid rgba(255,255,255,.14);
}
.hero-impact .hi-cell:not(:first-child) { padding-left: 28px; }
.hero-impact .hi-cell:last-child { border-right: none; padding-right: 0; }
.hero-impact .hi-n {
  font-family: var(--font-display); font-weight: 700;
  font-size: 1.65rem; letter-spacing: -.025em;
  color: #fff; line-height: 1;
}
.hero-impact .hi-n em { color: var(--accent); font-style: normal; }
.hero-impact .hi-l {
  font-size: .72rem; color: rgba(255,255,255,.72);
  margin-top: 8px; letter-spacing: .02em;
  font-family: var(--font-body);
}
.hero-impact-eyebrow {
  font-family: var(--font-display); font-size: .68rem; font-weight: 600;
  letter-spacing: .18em; text-transform: uppercase;
  color: rgba(255,255,255,.65);
  margin-bottom: 10px;
  display: inline-flex; align-items: center; gap: 8px;
}
.hero-impact-eyebrow::before {
  content:''; width:6px; height:6px; border-radius:50%; background: var(--accent);
}

.hero-btns { display: flex; gap: 14px; flex-wrap: wrap; align-items: center; }
.hero .btn-accent {
  padding: 15px 30px; font-size: 1rem;
  box-shadow: 0 8px 24px rgba(231,96,33,.35);
}
.hero .btn-ghost {
  background: rgba(255,255,255,.08); color:#fff;
  font-family: var(--font-display); font-size:1rem; font-weight:600;
  padding: 14px 28px; border-radius: var(--radius-full);
  border: 1.5px solid rgba(255,255,255,.25);
  cursor: pointer; display:inline-flex; align-items:center; gap:8px;
  backdrop-filter: blur(8px);
  transition: background .15s, border-color .15s;
}
.hero .btn-ghost:hover { background: rgba(255,255,255,.16); border-color: rgba(255,255,255,.55); color:#fff; }
.hero-listen {
  margin-left: 8px; display:inline-flex; align-items:center; gap:8px;
  font-family: var(--font-display); font-size:.82rem; font-weight:500;
  color: rgba(255,255,255,.78); background:none; border:none; cursor:pointer;
  padding: 8px 4px;
}
.hero-listen:hover { color: #fff; }
.hero-listen i { font-size: 18px; }

/* Preserve legacy panel hidden (Tweak "quote" still targets .hero-panel) */
.hero-panel { display:none !important; }

[data-theme="dark"] .hero-photo,
[data-theme="high-contrast"] .hero-photo {
  filter: saturate(.8) contrast(1.1) brightness(.85);
}
[data-theme="high-contrast"] .hero-photo::after { background: linear-gradient(115deg, rgba(0,0,0,.6) 0%, rgba(0,0,0,.2) 50%, rgba(0,0,0,.6) 100%); mix-blend-mode: normal; }

.btn-primary { background: var(--brand); color: #fff; font-family: var(--font-display); font-size: 1rem; font-weight: 600; padding: 14px 28px; border-radius: var(--radius-full); border: none; cursor: pointer; transition: background .15s, transform .1s; display: inline-flex; align-items: center; gap: 8px; }
.btn-primary:hover { background: var(--brand-hover); color: #fff; }
.btn-primary:active { transform: scale(.97); }
.btn-secondary { background: transparent; color: var(--fg); font-family: var(--font-display); font-size: 1rem; font-weight: 600; padding: 13px 27px; border-radius: var(--radius-full); border: 2px solid var(--border-strong); cursor: pointer; transition: border-color .15s, color .15s, transform .1s; display: inline-flex; align-items: center; gap: 8px; }
.btn-secondary:hover { border-color: var(--brand); color: var(--brand); }
.btn-accent { background: var(--accent); color: #fff; font-family: var(--font-display); font-size: 1rem; font-weight: 600; padding: 14px 28px; border-radius: var(--radius-full); border: none; cursor: pointer; transition: background .15s, transform .1s; display: inline-flex; align-items: center; gap: 8px; }
.btn-accent:hover { background: var(--accent-hover); color: #fff; }

.hero-panel { background: var(--bg-elevated); border: 1px solid var(--border); border-radius: var(--radius-xl); padding: 32px; box-shadow: var(--shadow-lg); position: relative; overflow: hidden; }
.hero-panel::before { content: ''; position: absolute; top: -40px; right: -40px; width: 180px; height: 180px; border-radius: 50%; background: var(--brand-subtle); opacity: .7; z-index: 0; }
.hero-panel-inner { position: relative; z-index: 1; }
.hero-panel-label { font-family: var(--font-display); font-size: .7rem; font-weight: 600; letter-spacing: .12em; text-transform: uppercase; color: var(--fg-muted); margin-bottom: 8px; display: flex; align-items: center; gap: 8px; }
.hero-panel-label .dot { width: 8px; height: 8px; background: var(--accent); border-radius: 50%; animation: pulse 2s ease-in-out infinite; }
@keyframes pulse { 0%,100%{opacity:1;} 50%{opacity:.4;} }
.hero-panel h4 { font-family: var(--font-display); font-weight: 600; font-size: 1.1rem; color: var(--fg); margin-bottom: 18px; letter-spacing: -.01em; }
.hero-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-bottom: 20px; }
.hero-stat { padding: 16px; background: var(--bg); border-radius: var(--radius-md); border: 1px solid var(--border); }
.hero-stat .n { font-family: var(--font-display); font-size: 1.6rem; font-weight: 700; color: var(--fg); line-height: 1; letter-spacing: -.02em; }
.hero-stat .n em { color: var(--brand); font-style: normal; }
.hero-stat .l { font-size: .75rem; color: var(--fg-muted); margin-top: 6px; }
.hero-quote { font-family: var(--font-display); font-size: .9rem; color: var(--fg-muted); line-height: 1.55; padding: 14px 16px; background: var(--bg); border-left: 3px solid var(--accent); border-radius: 0 var(--radius-md) var(--radius-md) 0; font-style: italic; }
.hero-quote cite { display: block; margin-top: 6px; font-style: normal; font-size: .72rem; letter-spacing: .08em; text-transform: uppercase; color: var(--fg-subtle); }

/* ── STATS BAND ───────────────────── */
.stats-band { background: var(--bg-inverse); color: var(--fg-inverse); padding: 56px var(--space-8); }
[data-theme="dark"] .stats-band, [data-theme="high-contrast"] .stats-band { background: var(--bg-subtle); color: var(--fg); }
.stats-band .section-inner { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; }
.stat-block { text-align: left; border-left: 2px solid rgba(255,255,255,.1); padding-left: 24px; }
[data-theme="dark"] .stat-block, [data-theme="high-contrast"] .stat-block { border-left-color: var(--border); }
.stat-block .num { font-family: var(--font-display); font-size: 2.75rem; font-weight: 700; color: #fff; display: block; letter-spacing: -.02em; line-height: 1; }
[data-theme="dark"] .stat-block .num, [data-theme="high-contrast"] .stat-block .num { color: var(--brand); }
.stat-block .lbl { font-size: .9rem; opacity: .75; margin-top: 10px; line-height: 1.45; }

/* ── SECTION HEADING ──────────────── */
.section-heading { text-align: center; margin-bottom: var(--space-12); }
.section-eyebrow { font-family: var(--font-display); font-size: .72rem; font-weight: 600; letter-spacing: .16em; text-transform: uppercase; color: var(--brand); margin-bottom: 14px; }
.section-title { font-family: var(--font-display); font-size: clamp(1.85rem, 3.2vw, 2.75rem); font-weight: 700; letter-spacing: -.03em; color: var(--fg); margin-bottom: 14px; text-wrap: balance; line-height: 1.1; }
.section-subtitle { font-size: 1.1rem; color: var(--fg-muted); max-width: 640px; margin: 0 auto; line-height: 1.65; }
.section-heading.left { text-align: left; }
.section-heading.left .section-subtitle { margin: 0; }

/* ── FEATURE GRID ─────────────────── */
.feature-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.feature-card { background: var(--bg-elevated); border-radius: var(--radius-lg); padding: 28px; border: 1px solid var(--border); box-shadow: var(--shadow-sm); transition: box-shadow .2s, transform .2s; }
.feature-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.feature-icon { width: 48px; height: 48px; border-radius: var(--radius-md); background: var(--brand-subtle); color: var(--brand); display: flex; align-items: center; justify-content: center; font-size: 22px; margin-bottom: 16px; }
.feature-card h3 { font-family: var(--font-display); font-size: 1.15rem; font-weight: 700; color: var(--fg); margin-bottom: 8px; letter-spacing: -.01em; }
.feature-card p { font-size: .92rem; color: var(--fg-muted); line-height: 1.6; }
.feature-card .card-link { display: inline-flex; align-items: center; gap: 5px; font-family: var(--font-display); font-size: .85rem; font-weight: 600; color: var(--brand); margin-top: 14px; }
.feature-card .card-link:hover { color: var(--brand-hover); }

/* ── PROG CARD ────────────────── */
.prog-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.prog-card { background: var(--bg-elevated); border-radius: var(--radius-lg); padding: 32px; border: 1px solid var(--border); box-shadow: var(--shadow-sm); display: flex; gap: 24px; align-items: flex-start; transition: box-shadow .2s, transform .2s; }
.prog-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.prog-icon { width: 56px; height: 56px; border-radius: var(--radius-lg); background: var(--accent-subtle); color: var(--accent); display: flex; align-items: center; justify-content: center; font-size: 26px; flex-shrink: 0; }
.prog-content { flex: 1; }
.prog-content h3 { font-family: var(--font-display); font-size: 1.15rem; font-weight: 700; color: var(--fg); margin-bottom: 8px; letter-spacing: -.01em; }
.prog-content p { font-size: .92rem; color: var(--fg-muted); line-height: 1.65; }
.prog-tag { display: inline-block; margin-top: 12px; font-family: var(--font-display); font-size: .7rem; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; background: var(--brand-subtle); color: var(--brand); padding: 4px 10px; border-radius: var(--radius-full); }

/* ── PAGE HERO (smaller for subpages) ─────────── */
.page-hero { padding: 72px var(--space-8) 56px; border-bottom: 1px solid var(--border); background: var(--bg); }
.page-hero-inner { max-width: var(--maxw); margin: 0 auto; }
.page-hero h1 { font-family: var(--font-display); font-size: clamp(2rem, 3.5vw, 3rem); font-weight: 700; letter-spacing: -.03em; color: var(--fg); margin-bottom: 14px; line-height: 1.1; }
.page-hero h1 em { color: var(--brand); font-style: normal; }
.page-hero p { font-size: 1.1rem; color: var(--fg-muted); max-width: 700px; line-height: 1.65; }

/* ── DONATE ───────────────────── */
.donate-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 56px; align-items: start; }
.donate-toggle { display: flex; background: var(--bg-subtle); border-radius: var(--radius-full); padding: 4px; gap: 4px; margin-bottom: 28px; border: 1px solid var(--border); }
.donate-toggle button { flex: 1; padding: 11px 20px; background: none; border: none; border-radius: var(--radius-full); font-family: var(--font-display); font-size: .92rem; font-weight: 600; color: var(--fg-muted); cursor: pointer; transition: all .2s ease; display: inline-flex; align-items: center; justify-content: center; gap: 6px; }
.donate-toggle button.active { background: var(--bg-elevated); color: var(--fg); box-shadow: var(--shadow-sm); }
.donate-toggle button.active .t-label { color: var(--brand); }
.amount-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-bottom: 20px; }
.amount-btn { background: var(--bg-elevated); border: 1.5px solid var(--border); border-radius: var(--radius-md); padding: 20px 12px; text-align: center; cursor: pointer; transition: all .15s; font-family: var(--font-display); }
.amount-btn:hover { border-color: var(--brand); }
.amount-btn.selected { border-color: var(--brand); background: var(--brand-subtle); }
.amount-btn .amt { font-size: 1.6rem; font-weight: 700; color: var(--fg); letter-spacing: -.01em; }
.amount-btn.selected .amt { color: var(--brand); }
.amount-btn .imp { font-size: .72rem; color: var(--fg-muted); margin-top: 6px; font-family: var(--font-body); line-height: 1.35; }
.custom-amount { display: flex; align-items: center; gap: 10px; background: var(--bg-elevated); border: 1.5px solid var(--border); border-radius: var(--radius-md); padding: 14px 18px; margin-bottom: 20px; }
.custom-amount .cur { font-family: var(--font-display); font-size: 1.3rem; font-weight: 600; color: var(--fg-muted); }
.custom-amount input { flex: 1; border: none; background: transparent; outline: none; font-family: var(--font-display); font-size: 1.3rem; font-weight: 600; color: var(--fg); }
.custom-amount input::placeholder { color: var(--fg-subtle); font-weight: 400; }
.custom-amount-suffix { font-family: var(--font-display); font-size: .9rem; color: var(--fg-muted); }

/* Standalone amount input (since the v2 update — donor types any amount,
   no preset tier grid). */
.custom-amount-solo { display: flex; flex-direction: column; gap: 8px; margin-bottom: 18px; }
.custom-amount-solo .custom-amount-label {
  font-family: var(--font-display); font-size: .82rem; font-weight: 600;
  letter-spacing: .04em; color: var(--fg);
}
.custom-amount-solo .custom-amount-input {
  display: flex; align-items: center; gap: 10px;
  background: var(--bg-elevated);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-md);
  padding: 18px 20px;
  transition: border-color .15s, box-shadow .15s;
}
.custom-amount-solo .custom-amount-input:focus-within {
  border-color: var(--brand);
  box-shadow: 0 0 0 4px var(--brand-subtle);
}
.custom-amount-solo .cur {
  font-family: var(--font-display); font-size: 1.6rem; font-weight: 700;
  color: var(--fg-muted);
}
.custom-amount-solo input {
  flex: 1; border: none; background: transparent; outline: none;
  font-family: var(--font-display); font-size: 1.6rem; font-weight: 700;
  color: var(--fg); min-width: 0;
}
.custom-amount-solo input::placeholder { color: var(--fg-subtle); font-weight: 500; }
.custom-amount-solo .custom-amount-suffix {
  font-family: var(--font-display); font-size: 1rem; font-weight: 500;
  color: var(--fg-muted); flex-shrink: 0;
}
.custom-amount-help {
  font-size: .82rem; color: var(--fg-muted); margin: 2px 4px 0;
}

.donate-impact { background: var(--bg-elevated); border: 1px solid var(--border); border-radius: var(--radius-xl); padding: 32px; box-shadow: var(--shadow-md); }
.donate-impact h3 { font-family: var(--font-display); font-size: 1.2rem; font-weight: 700; color: var(--fg); margin-bottom: 8px; }
.donate-impact .lead { color: var(--fg-muted); margin-bottom: 20px; font-size: .95rem; line-height: 1.65; }
.donate-impact-foot { color: var(--fg-muted); margin-top: 18px; font-size: .9rem; line-height: 1.6; font-style: italic; }
.impact-row { display: flex; align-items: flex-start; gap: 14px; padding: 14px 0; border-bottom: 1px solid var(--border); }
.impact-row:last-of-type { border-bottom: none; }
.impact-icon { width: 36px; height: 36px; border-radius: var(--radius-md); background: var(--accent-subtle); color: var(--accent); display: flex; align-items: center; justify-content: center; font-size: 17px; flex-shrink: 0; }
.impact-row .text { flex: 1; }
.impact-row .text strong { font-family: var(--font-display); font-weight: 600; color: var(--fg); display: block; font-size: .92rem; }
.impact-row .text span { font-size: .82rem; color: var(--fg-muted); }

.pay-field { display: flex; flex-direction: column; gap: 6px; margin-bottom: 14px; }
.pay-field label { font-family: var(--font-display); font-size: .78rem; font-weight: 600; color: var(--fg); letter-spacing: .02em; }
.pay-field input, .pay-field select { font-family: var(--font-body); font-size: .95rem; color: var(--fg); background: var(--bg); border: 1.5px solid var(--border); border-radius: var(--radius-md); padding: 11px 14px; outline: none; transition: border-color .15s, box-shadow .15s; }
.pay-field input:focus, .pay-field select:focus { border-color: var(--brand); box-shadow: 0 0 0 3px rgba(31,97,255,.15); }
.pay-row { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }

/* ── MEDIA GRID ───────────────────── */
.photo-grid { display: grid; grid-template-columns: repeat(12, 1fr); gap: 16px; grid-auto-rows: 180px; }
.photo-tile { border-radius: var(--radius-lg); overflow: hidden; position: relative; cursor: pointer; transition: transform .3s ease; background: var(--bg-subtle); border: 1px solid var(--border); }
/* Strip default <button> chrome when .photo-tile is rendered as a
   button (since the FRONTEND_FIXES a11y migration). Browser handles
   Enter/Space activation and focus-visible automatically. */
button.photo-tile {
  font: inherit; color: inherit; text-align: left;
  padding: 0; margin: 0; appearance: none;
  width: 100%; display: block;
}
button.photo-tile:focus-visible {
  outline: 3px solid var(--brand);
  outline-offset: 3px;
}
.photo-tile:hover { transform: scale(1.015); }
.photo-tile .overlay { position: absolute; inset: 0; padding: 18px; display: flex; flex-direction: column; justify-content: flex-end; background: linear-gradient(180deg, transparent 40%, rgba(13,4,7,.8) 100%); color: #fff; opacity: 0; transition: opacity .2s; }
.photo-tile:hover .overlay { opacity: 1; }
.photo-tile .ph-title { font-family: var(--font-display); font-size: .95rem; font-weight: 600; }
.photo-tile .ph-meta { font-size: .75rem; opacity: .8; margin-top: 3px; letter-spacing: .04em; text-transform: uppercase; }
.photo-tile .ph-img-bg { position: absolute; inset: 0; background-size: cover; background-position: center; }
.photo-tile .ph-placeholder { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-family: var(--font-display); font-weight: 700; font-size: 2rem; color: var(--fg-subtle); opacity: .3; }

.p-6-4 { grid-column: span 6; grid-row: span 2; }
.p-4-2 { grid-column: span 4; grid-row: span 1; }
.p-4-4 { grid-column: span 4; grid-row: span 2; }
.p-3-2 { grid-column: span 3; grid-row: span 1; }
.p-6-2 { grid-column: span 6; grid-row: span 1; }
.p-8-2 { grid-column: span 8; grid-row: span 1; }

.pod-list { display: flex; flex-direction: column; gap: 16px; }
.pod-row { display: flex; gap: 20px; align-items: center; background: var(--bg-elevated); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 20px; box-shadow: var(--shadow-sm); transition: box-shadow .2s, transform .2s; }
.pod-row:hover { box-shadow: var(--shadow-md); transform: translateY(-1px); }
.pod-art { width: 88px; height: 88px; border-radius: var(--radius-md); flex-shrink: 0; background: linear-gradient(135deg, var(--brand) 0%, var(--accent) 100%); display: flex; align-items: center; justify-content: center; color: #fff; font-family: var(--font-display); font-weight: 700; font-size: 1.4rem; letter-spacing: -.02em; position: relative; overflow: hidden; }
.pod-art.v2 { background: linear-gradient(135deg, #1349d4 0%, #4d7eff 100%); }
.pod-art.v3 { background: linear-gradient(135deg, #e76021 0%, #f07a3d 100%); }
.pod-art.v4 { background: linear-gradient(135deg, #0d0407 0%, #4a4a6a 100%); }
.pod-art.v5 { background: linear-gradient(135deg, #1f61ff 0%, #1e1a2e 100%); }
.pod-body { flex: 1; }
.pod-body .ep { font-family: var(--font-display); font-size: .72rem; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; color: var(--brand); margin-bottom: 4px; }
.pod-body h4 { font-family: var(--font-display); font-size: 1.05rem; font-weight: 700; color: var(--fg); margin-bottom: 4px; letter-spacing: -.01em; }
.pod-body p { font-size: .88rem; color: var(--fg-muted); line-height: 1.5; margin-bottom: 8px; }
.pod-meta { display: flex; gap: 14px; font-size: .78rem; color: var(--fg-subtle); font-family: var(--font-display); }
.pod-meta span { display: inline-flex; align-items: center; gap: 4px; }
.pod-play { width: 48px; height: 48px; border-radius: 50%; background: var(--brand); color: #fff; border: none; cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 18px; flex-shrink: 0; transition: background .15s, transform .1s; }
.pod-play:hover { background: var(--brand-hover); }
.pod-play:active { transform: scale(.93); }

.video-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.video-card { background: var(--bg-elevated); border: 1px solid var(--border); border-radius: var(--radius-lg); overflow: hidden; box-shadow: var(--shadow-sm); transition: box-shadow .2s, transform .2s; cursor: pointer; }
.video-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.video-thumb { aspect-ratio: 16/9; position: relative; background: linear-gradient(135deg, var(--bg-subtle) 0%, var(--bg) 100%); border-bottom: 1px solid var(--border); display: flex; align-items: center; justify-content: center; overflow: hidden; }
.video-thumb .play-btn { width: 64px; height: 64px; border-radius: 50%; background: rgba(255,255,255,.95); color: var(--brand); display: flex; align-items: center; justify-content: center; font-size: 22px; z-index: 2; box-shadow: var(--shadow-md); transition: transform .15s; }
.video-card:hover .play-btn { transform: scale(1.1); }
.video-thumb .dur { position: absolute; bottom: 10px; right: 10px; background: rgba(0,0,0,.75); color: #fff; font-family: var(--font-display); font-size: .72rem; font-weight: 600; padding: 3px 8px; border-radius: 4px; z-index: 2; }
.video-thumb .cc { position: absolute; bottom: 10px; left: 10px; background: rgba(255,255,255,.9); color: var(--fg); font-family: var(--font-display); font-size: .65rem; font-weight: 700; padding: 3px 6px; border-radius: 3px; letter-spacing: .05em; z-index: 2; }
.video-body { padding: 18px 20px 22px; }
.video-body h4 { font-family: var(--font-display); font-size: 1rem; font-weight: 700; color: var(--fg); margin-bottom: 6px; letter-spacing: -.01em; line-height: 1.25; }
.video-body p { font-size: .85rem; color: var(--fg-muted); line-height: 1.5; margin-bottom: 10px; }
.video-meta { font-size: .75rem; color: var(--fg-subtle); font-family: var(--font-display); display: flex; gap: 10px; align-items: center; }
.video-meta .sep { opacity: .5; }

.vid-bg-1 { background: linear-gradient(135deg, #1f61ff 0%, #4d7eff 100%); }
.vid-bg-2 { background: linear-gradient(135deg, #e76021 0%, #f07a3d 100%); }
.vid-bg-3 { background: linear-gradient(135deg, #0d0407 0%, #4a4a6a 100%); }
.vid-bg-4 { background: linear-gradient(135deg, #4d7eff 0%, #c04c18 100%); }
.vid-bg-5 { background: linear-gradient(135deg, #1349d4 0%, #0d0410 100%); }
.vid-bg-6 { background: linear-gradient(135deg, #fff4ee 0%, #eaeaf5 100%); }
.vid-inner-label { position: absolute; top: 14px; left: 14px; color: #fff; font-family: var(--font-display); font-size: .75rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; opacity: .85; }
.vid-bg-6 .vid-inner-label { color: var(--fg); }

/* ── DOCUMENTS / BLOG / STORIES ─────── */
/*
 * Doc grid (stories/blogs tiles): auto-fit so any extra cards wrap to
 * the next row cleanly, with a sensible minimum per card so the hero
 * titles never collapse into one-word-per-line columns. The featured
 * card opts in to spanning two tracks for visual weight on home + the
 * documents archive.
 */
.doc-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
}
.doc-grid > .doc-card.featured { grid-column: span 2; }
@media (max-width: 720px) {
  .doc-grid > .doc-card.featured { grid-column: auto; }
}

/* ── BOOK TAB (Documents → Book) ─────────────────────────────
   Founder's memoir-in-progress: low-key, list-based layout, no card
   imagery. Per the v2 content update — quiet placement, off the main
   archive. */
.book-intro { max-width: 720px; margin: 0 auto 48px; text-align: left; }
.book-intro .section-eyebrow { margin-bottom: 14px; }
.book-title { font-family: var(--font-display); font-size: clamp(1.85rem, 3vw, 2.5rem); font-weight: 700; letter-spacing: -.02em; line-height: 1.15; color: var(--fg); margin-bottom: 14px; text-wrap: balance; }
.book-byline { display: inline-flex; align-items: center; gap: 8px; font-family: var(--font-display); font-size: .9rem; font-weight: 600; color: var(--brand); margin-bottom: 18px; }
.book-intro-text { font-size: 1.02rem; line-height: 1.7; color: var(--fg-muted); }

.book-chapters { list-style: none; padding: 0; margin: 0; max-width: 760px; counter-reset: book; }
.book-chapter {
  counter-increment: book;
  padding: 28px 0;
  border-top: 1px solid var(--border);
}
.book-chapter:last-child { border-bottom: 1px solid var(--border); }
.book-chapter-meta {
  display: flex; align-items: center; gap: 18px;
  font-family: var(--font-display); font-size: .76rem; font-weight: 700;
  letter-spacing: .14em; text-transform: uppercase;
  color: var(--fg-subtle);
  margin-bottom: 8px;
}
.book-chapter-num { color: var(--accent); }
.book-chapter-readtime { display: inline-flex; align-items: center; gap: 6px; }
.book-chapter-title {
  font-family: var(--font-display); font-size: 1.4rem; font-weight: 700;
  letter-spacing: -.015em; color: var(--fg); line-height: 1.25;
  margin-bottom: 10px; text-wrap: balance;
}
.book-chapter-snippet {
  font-size: 1rem; line-height: 1.65; color: var(--fg-muted);
  max-width: 64ch; margin-bottom: 12px;
}
.book-chapter-status {
  display: inline-block;
  font-family: var(--font-display); font-size: .72rem; font-weight: 700;
  letter-spacing: .1em; text-transform: uppercase;
  color: var(--fg-subtle);
  padding: 4px 10px; border: 1px solid var(--border);
  border-radius: var(--radius-full);
  background: var(--bg-elevated);
}
.book-foot {
  max-width: 760px; margin: 36px 0 0;
  font-size: .92rem; line-height: 1.65;
  color: var(--fg-muted);
}

.doc-card {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: box-shadow .2s, transform .2s;
  display: flex;
  flex-direction: column;
  min-width: 0; /* let the grid shrink this below intrinsic content */
  text-decoration: none;
  color: inherit;
}
.doc-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.doc-hero { aspect-ratio: 16/10; display: flex; align-items: flex-end; padding: 28px; position: relative; overflow: hidden; min-width: 0; }
.doc-card.featured .doc-hero { aspect-ratio: 16/9; }
.doc-card .cat-tag { font-family: var(--font-display); font-size: .7rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; padding: 4px 10px; border-radius: var(--radius-full); align-self: flex-start; margin-bottom: 10px; }
.doc-hero.type-blog { background: linear-gradient(135deg, var(--brand) 0%, #1349d4 100%); color: #fff; }
.doc-hero.type-story { background: linear-gradient(135deg, var(--accent) 0%, #c04c18 100%); color: #fff; }
.doc-hero.type-report { background: linear-gradient(135deg, #0d0407 0%, #1e1a2e 100%); color: #fff; }
.doc-hero.type-policy { background: linear-gradient(135deg, #eaeaf5 0%, #d4d4e8 100%); color: var(--fg); }
.doc-hero.type-tutorial { background: linear-gradient(135deg, #eef3ff 0%, #d6e4ff 100%); color: var(--fg); }
.doc-hero.type-story2 { background: linear-gradient(135deg, #f07a3d 0%, #ffaa5c 100%); color: #fff; }
.doc-hero h3 {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -.02em;
  color: inherit;
  text-wrap: pretty;
  overflow-wrap: break-word;
  hyphens: auto;
}
.doc-card.featured .doc-hero h3 { font-size: 1.75rem; }
.doc-body { padding: 18px 22px 22px; display: flex; flex-direction: column; gap: 10px; flex: 1; min-width: 0; }
.doc-body p {
  font-size: .88rem;
  color: var(--fg-muted);
  line-height: 1.55;
  flex: 1;
  overflow-wrap: break-word;
  hyphens: auto;
}
.doc-meta { font-size: .75rem; color: var(--fg-subtle); font-family: var(--font-display); display: flex; gap: 10px; align-items: center; }
.doc-author { display: flex; align-items: center; gap: 8px; }
.doc-author .avatar { width: 22px; height: 22px; border-radius: 50%; background: var(--bg-subtle); border: 1px solid var(--border); font-family: var(--font-display); font-weight: 700; font-size: .7rem; color: var(--fg-muted); display: flex; align-items: center; justify-content: center; }

.cat-tag.blog { background: rgba(255,255,255,.25); color: #fff; backdrop-filter: blur(4px); }
.cat-tag.story { background: rgba(255,255,255,.25); color: #fff; backdrop-filter: blur(4px); }
.cat-tag.report { background: rgba(255,255,255,.15); color: #fff; }
.cat-tag.policy { background: rgba(13,4,7,.1); color: var(--fg); }
.cat-tag.tutorial { background: rgba(31,97,255,.18); color: var(--brand); }

/* ── TEAM ──────────────────────────── */
.team-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }

/* Board recruit card — sits below the team grid on /about → Team. v2 */
.board-recruit-card {
  margin-top: 36px;
  padding: 28px 32px;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-left: 4px solid var(--brand);
  border-radius: var(--radius-lg);
  display: flex; flex-direction: column; gap: 12px; align-items: flex-start;
  max-width: 720px;
}
.board-recruit-card h3 {
  font-family: var(--font-display);
  font-size: 1.25rem; font-weight: 700;
  letter-spacing: -.015em; color: var(--fg);
}
.board-recruit-card p {
  font-size: .98rem; line-height: 1.65; color: var(--fg-muted);
}

/* Founder's Series — small list, no card imagery, anchored at the
   bottom of /about. Optional, low-key per v2. */
.founders-series-list {
  list-style: none; padding: 0; margin: 0; counter-reset: fs;
  border-top: 1px solid var(--border);
}
.founders-series-list li {
  display: flex; align-items: baseline; gap: 14px;
  padding: 16px 4px;
  border-bottom: 1px solid var(--border);
  counter-increment: fs;
}
.founders-series-list .fs-num {
  font-family: var(--font-display); font-size: .76rem; font-weight: 700;
  letter-spacing: .14em; color: var(--accent);
  flex-shrink: 0; min-width: 32px;
}
.founders-series-list .fs-title {
  flex: 1; font-family: var(--font-display); font-weight: 500;
  color: var(--fg); line-height: 1.3;
}
.founders-series-list .fs-time {
  font-size: .8rem; color: var(--fg-muted);
  font-family: var(--font-display); flex-shrink: 0;
}
.team-card { text-align: left; }
.team-photo { width: 100%; aspect-ratio: 1; border-radius: var(--radius-lg); margin-bottom: 16px; background: var(--bg-subtle); border: 1px solid var(--border); position: relative; overflow: hidden; display: flex; align-items: flex-end; padding: 20px; }
.team-photo::before { content: ''; position: absolute; inset: 0; background: linear-gradient(180deg, transparent 50%, rgba(13,4,7,.5) 100%); }
.team-photo .initials { position: relative; font-family: var(--font-display); font-weight: 700; font-size: 3.25rem; color: rgba(255,255,255,.9); letter-spacing: -.03em; line-height: 1; z-index: 1; }
.team-photo .team-photo-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; z-index: 0; }
.team-photo.has-img .initials { display: none; }
.team-photo.has-img::before { z-index: 1; }
.team-photo.bg-1 { background: linear-gradient(135deg, #1f61ff, #4d7eff); }
.team-photo.bg-2 { background: linear-gradient(135deg, #e76021, #f07a3d); }

import type { CSSProperties } from 'react';
import { Suspense } from 'react';
import Link from 'next/link';
import { SkeletonHero } from '@/components/Skeleton';
import { getContent, visibleSorted } from '@/lib/cms/db';
import RichText from '@/components/RichText';
import JsonLd from '@/components/JsonLd';
import ImpactCell from '@/components/home/ImpactCell';
import StatBlock from '@/components/home/StatBlock';
import ValueCard from '@/components/home/ValueCard';
import HeroGraphics from '@/components/home/HeroGraphics';
import HeroActions from '@/components/home/HeroActions';
import Reveal from '@/components/Reveal';
import HeartPulseIcon from '@/components/animate-ui/icons/heart-pulse';
import { Button } from '@/components/ui/button';
import StoryCard from '@/components/cards/StoryCard';
import TimelineRow from '@/components/cards/TimelineRow';
import ProjectCard from '@/components/projects/ProjectCard';
import { pageMetadata, readSeoOverrides, webPageJsonLd } from '@/lib/seo';
import { ArrowRight, ArrowUpRight, Clock, Star } from '@/components/icons';

// Home is CMS-driven and revalidatePath('/') fires from /api/cms/data
// on every publish — the hourly fallback only runs if a publish was
// missed for some reason. Per HIGH-3.
export const revalidate = 3600;

export async function generateMetadata() {
  const content = await getContent();
  const o = readSeoOverrides(content, '/');
  return pageMetadata({
    title: o.title || content?.site?.title,
    description: o.description,
    path: '/',
    image: o.image,
    noindex: o.noindex,
  });
}

export default function HomePage() {
  return (
    <Suspense fallback={<SkeletonHero />}>
      <HomePageContent />
    </Suspense>
  );
}

async function HomePageContent() {
  // If the DB is briefly unreachable (cold-start lock, transient
  // connection drop), render the page with empty CMS sections rather
  // than throwing all the way out to the error boundary. getContent()
  // already returns null on JSON parse errors; this catch handles
  // connection-level failures the same way.
  let content = null;
  try {
    content = await getContent();
  } catch {
    // intentional empty — fall through to the empty-content render
  }
  const h = content?.home || {};
  const docs = content?.documents || {};
  const projectsSection = content?.projects || content?.programs || {};
  const impactStats = visibleSorted(h.impactStats || []);
  const statsBand   = visibleSorted(h.statsBand   || []);
  const values      = visibleSorted(h.coreValues  || []);
  const projectItems = visibleSorted(projectsSection.items || []);
  const stories     = visibleSorted(docs.stories  || []);
  const blogs       = visibleSorted(docs.blogs    || []);

  const showLiveLabel = h.liveLabelEnabled !== false && !!h.liveLabel;
  const showImpact    = h.impactEnabled    !== false && impactStats.length > 0;

  const latest = [stories[0], blogs[0], stories[1]].filter(Boolean);
  const timelineStories = stories.slice(0, 5);
  const featured = timelineStories[0] || docs.featuredStory || {};

  return (
    <>
      <JsonLd data={webPageJsonLd({ title: h.heroEyebrow ? 'Home' : undefined, path: '/' })} />
      <section className="hero">
        <div
          className="hero-photo"
          aria-hidden="true"
          style={
            (h.heroImage as string | undefined)
              ? ({ '--hero-image': `url('${h.heroImage}')` } as CSSProperties)
              : undefined
          }
        ></div>
        <HeroGraphics liveLabel={showLiveLabel ? h.liveLabel : null} />
        <Reveal as="div" className="hero-inner" stagger={0.1} delay={0.1} y={18}>
          {h.heroEyebrow ? <div className="hero-eyebrow">{h.heroEyebrow}</div> : null}
          <RichText as="h1" className="hero-title" html={h.heroTitle || ''} />
          {h.heroSub ? <p className="hero-sub">{h.heroSub}</p> : null}
          {showImpact && h.impactEyebrow ? (
            <div className="hero-impact-eyebrow">{h.impactEyebrow}</div>
          ) : null}
          {showImpact ? (
            <div className="hero-impact">
              {impactStats.map((s, i) => <ImpactCell key={s.id || i} stat={s} />)}
            </div>
          ) : null}
          <HeroActions />
        </Reveal>
      </section>

      {statsBand.length > 0 ? (
        <div className="stats-band">
          <div className="section-inner">
            {statsBand.map((s, i) => <StatBlock key={s.id || i} stat={s} />)}
          </div>
        </div>
      ) : null}

      {values.length > 0 ? (
        <section className="values-section">
          <div className="values-bg" aria-hidden="true">
            <span className="vbg-ring r1"></span>
            <span className="vbg-ring r2"></span>
          </div>
          <div className="section-inner values-inner">
            <header className="values-head">
              {h.coreValuesEyebrow ? <div className="section-eyebrow">{h.coreValuesEyebrow}</div> : null}
              <RichText as="h2" className="values-title" html={h.coreValuesTitle || ''} />
              {h.coreValuesSub ? <p className="values-sub">{h.coreValuesSub}</p> : null}
            </header>
            <ol className="values-grid" role="list">
              {values.map((v, i) => <ValueCard key={v.id || i} value={v} />)}
            </ol>
          </div>
        </section>
      ) : null}

      {projectItems.length > 0 ? (
        <section className="section">
          <div className="section-inner">
            <div className="section-heading">
              <div className="section-eyebrow">What We Build</div>
              <h2 className="section-title">Voice-first tools, built with our community</h2>
              <p className="section-subtitle">
                Two active projects — a voice navigator for the web, and a social network for
                blind and low-vision users. Each starts from voice, not vision.
              </p>
            </div>
            <div className="home-projects-grid">
              {projectItems.map((p) => <ProjectCard key={p.id || p.slug} project={p} />)}
            </div>
          </div>
        </section>
      ) : null}

      {latest.length > 0 ? (
        <section className="section section-alt">
          <div className="section-inner">
            <div className="section-heading left" style={{ maxWidth: 720 }}>
              <div className="section-eyebrow">Latest Stories</div>
              <h2 className="section-title">Voices from our community</h2>
              <p className="section-subtitle">
                Real people, real independence. The work is never about us — it&apos;s about what
                becomes possible.
              </p>
            </div>
            <div className="doc-grid">
              {latest.map((s, i) => (
                <StoryCard key={s.id || i} story={s} featured={i === 0} />
              ))}
            </div>
          </div>
        </section>
      ) : null}

      {timelineStories.length > 0 ? (
        <section className="story-timeline">
          <div className="section-inner">
            <header className="story-head">
              <div className="story-eyebrow">
                <span className="ribbon-dot"></span>
                <span>The Archive</span>
                <span className="story-count">· {new Date().getFullYear()}</span>
              </div>
              <h2 className="story-h2">
                Every story we&apos;ve published,
                <br />
                <em>newest first.</em>
              </h2>
            </header>

            <Link href="/documents#stories" className="story-featured" aria-label={featured.title}>
              <div className="sf-media" aria-hidden="true">
                <div className="sf-photo"></div>
                <svg className="sf-rings" viewBox="0 0 400 400" fill="none" stroke="currentColor" strokeWidth="1">
                  <circle cx="200" cy="200" r="60" />
                  <circle cx="200" cy="200" r="110" strokeDasharray="2 6" />
                  <circle cx="200" cy="200" r="160" />
                </svg>
                <div className="sf-badge">
                  <Star weight="fill" size="1em" aria-hidden="true" />
                  <span>Newest story</span>
                </div>
              </div>
              <div className="sf-body">
                <div className="sf-meta-top">
                  <span className="cat-tag story">Story</span>
                  <span className="sf-read">
                    <Clock size="1em" aria-hidden="true" />{' '}
                    {featured.meta || featured.readTime || '8 min read'}
                  </span>
                </div>
                <h3 className="sf-title">{featured.title || ''}</h3>
                <p className="sf-excerpt">{featured.desc || featured.excerpt || ''}</p>
                <div className="sf-footer">
                  <div className="sf-author">
                    <div className="avatar lg" aria-hidden="true">{featured.initials || 'TE'}</div>
                    <div className="sf-author-text">
                      <div className="sf-author-name">{featured.author || ''}</div>
                    </div>
                  </div>
                  <span className="sf-read-btn" role="presentation">
                    Read the full story <ArrowUpRight size="1em" aria-hidden="true" />
                  </span>
                </div>
              </div>
            </Link>

            <ol className="story-list" role="list">
              {timelineStories.map((s, i) => <TimelineRow key={s.id || i} story={s} />)}
            </ol>

            <div className="story-foot">
              <Button asChild variant="pillGhost" size="pill">
                <Link href="/documents#stories">
                  Browse the full archive <ArrowRight size="1em" aria-hidden="true" />
                </Link>
              </Button>
              <div className="story-foot-meta">
                Updated weekly · {stories.length} stories in the archive
              </div>
            </div>
          </div>
        </section>
      ) : null}

      <section className="cta-band">
        <div className="cta-inner">
          <h2>Your support opens worlds.</h2>
          <p>
            $10 a month connects one user for a full year. Every contribution funds free tools,
            free training, and free devices for those who need them most.
          </p>
          <div style={{ display: 'flex', gap: 14, flexWrap: 'wrap', justifyContent: 'center' }}>
            <Button asChild variant="accent" size="pill">
              <Link href="/donate">
                <HeartPulseIcon /> Donate Monthly
              </Link>
            </Button>
            <Button asChild variant="pillSecondary" size="pill">
              <Link href="/volunteers">Become a Volunteer</Link>
            </Button>
          </div>
        </div>
      </section>
    </>
  );
}

