1	// Data access for the public site's CMS-driven pages.
2	//
3	// PR 13 collapsed this file to two functions — getContent + visibleSorted.
4	// The prisma export is gone; admin server pages now go through
5	// `lib/admin-api.ts` which fetches from the Nest backend.
6	
7	import type { CmsItemMeta, SiteContent } from '@/lib/types';
8	
9	/**
10	 * Fetch the live SiteContent document from the Nest backend.
11	 *
12	 * Server-side only — calls Nest at BACKEND_INTERNAL_URL/api/content
13	 * (default http://127.0.0.1:3001 for both dev and prod, since the Nest
14	 * process is on the same host in both cases).
15	 *
16	 * The fetch is tagged 'site-content' with a 60-second revalidate window.
17	 * Publishes invalidate the tag via /api/internal/revalidate so editors
18	 * see fresh content within seconds of clicking Publish; uncached requests
19	 * pay the round-trip but cached pages serve instantly.
20	 *
21	 * Returns null on parse failure or if the backend is unreachable — pages
22	 * that depend on content fall back to their not-found UI rather than
23	 * crashing the dev server.
24	 */
25	export async function getContent(): Promise<SiteContent | null> {
26	  const baseUrl = process.env.BACKEND_INTERNAL_URL || 'http://127.0.0.1:3001';
27	  try {
28	    const res = await fetch(`${baseUrl}/api/content`, {
29	      next: { revalidate: 60, tags: ['site-content'] },
30	    });
31	    if (!res.ok) return null;
32	    const data = (await res.json()) as SiteContent;
33	    return data;
34	  } catch {
35	    return null;
36	  }
37	}
38	
39	/** Filter array-of-items by visibility + sort by `order`. */
40	export function visibleSorted<T extends CmsItemMeta>(items: unknown): T[] {
41	  if (!Array.isArray(items)) return [];
42	  return (items as T[])
