// Data access for the public site's CMS-driven pages.
//
// PR 13 collapsed this file to two functions — getContent + visibleSorted.
// The prisma export is gone; admin server pages now go through
// `lib/admin-api.ts` which fetches from the Nest backend.

import type { CmsItemMeta, SiteContent } from '@/lib/types';

/**
 * Fetch the live SiteContent document from the Nest backend.
 *
 * Server-side only — calls Nest at BACKEND_INTERNAL_URL/api/content
 * (default http://127.0.0.1:3001 for both dev and prod, since the Nest
 * process is on the same host in both cases).
 *
 * The fetch is tagged 'site-content' with a 60-second revalidate window.
 * Publishes invalidate the tag via /api/internal/revalidate so editors
 * see fresh content within seconds of clicking Publish; uncached requests
 * pay the round-trip but cached pages serve instantly.
 *
 * Returns null on parse failure or if the backend is unreachable — pages
 * that depend on content fall back to their not-found UI rather than
 * crashing the dev server.
 */
export async function getContent(): Promise<SiteContent | null> {
  const baseUrl = process.env.BACKEND_INTERNAL_URL || 'http://127.0.0.1:3001';
  try {
    const res = await fetch(`${baseUrl}/api/content`, {
      next: { revalidate: 60, tags: ['site-content'] },
    });
    if (!res.ok) return null;
    const data = (await res.json()) as SiteContent;
    return data;
  } catch {
    return null;
  }
}

/** Filter array-of-items by visibility + sort by `order`. */
export function visibleSorted<T extends CmsItemMeta>(items: unknown): T[] {
  if (!Array.isArray(items)) return [];
  return (items as T[])
    .filter((it): it is T => Boolean(it) && it.visible !== false)
    .slice()
    .sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
}

