import { notFound } from 'next/navigation';
import HtmlContent from '@/components/HtmlContent';
import { getContent } from '@/lib/cms/db';
import { findCustomPage, readCustomPages, renderCustomPage } from '@/lib/pages/custom';
import { pageMetadata, readSeoOverrides } from '@/lib/seo';

// Reserved slugs that already resolve to concrete routes; must not be shadowed
// by a user-defined page slug.
const RESERVED = new Set([
  'about', 'programs', 'projects', 'donate', 'media', 'documents',
  'volunteers', 'blog-detail', 'story-detail', 'coming-soon', 'admin', 'ad-min', 'api',
]);

// Static export: enumerate every CMS-defined page slug at build time so
// Next can prerender each one as its own .html file. Reads from the
// new pages.custom shape (CMS-03) and the legacy flat pages array via
// readCustomPages. If the backend is unreachable during build OR no
// custom pages exist yet, fall back to a single 404 placeholder so
// Next can still produce a buildable route.
export async function generateStaticParams() {
  const content = await getContent();
  const pages = readCustomPages(content);
  const params = pages
    .filter((p) => p && p.slug && p.visible !== false && !RESERVED.has(p.slug))
    .map((p) => ({ slug: p.slug }));
  if (params.length === 0) return [{ slug: '__placeholder__' }];
  return params;
}

interface SlugRouteProps {
  params: Promise<{ slug: string }>;
}

export async function generateMetadata({ params }: SlugRouteProps) {
  const { slug } = await params;
  if (RESERVED.has(slug)) return {};
  const content = await getContent();
  const page = findCustomPage(content, slug);
  if (!page) return {};
  const o = readSeoOverrides(content, '/' + slug);
  return pageMetadata({
    title: o.title || (page.title || slug),
    description: o.description || page.description || page.excerpt,
    path: '/' + slug,
    image: o.image || page.image,
    noindex: o.noindex,
  });
}

export default async function CustomPage({ params }: SlugRouteProps) {
  const { slug } = await params;
  if (RESERVED.has(slug)) notFound();
  const content = await getContent();
  const page = findCustomPage(content, slug);
  if (!page) notFound();

